create extension if not exists pgcrypto;
create table if not exists public.events (id uuid primary key default gen_random_uuid(), name text not null, category text not null check (category in ('kpop','tpop','other')), tag text not null, venue text not null, pickup text not null, base_price numeric(10,2) not null check (base_price >= 0), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.event_dates (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, event_date date not null, status text not null default 'available' check (status in ('available','pending','booked')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (event_id,event_date));
create table if not exists public.promotions (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events(id) on delete cascade, days integer not null check (days > 0), discount_amount numeric(10,2) not null default 0 check (discount_amount >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (event_id,days));
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path = public as $$ begin new.updated_at = now(); return new; end; $$;
drop trigger if exists events_updated_at on public.events; create trigger events_updated_at before update on public.events for each row execute function public.set_updated_at();
drop trigger if exists event_dates_updated_at on public.event_dates; create trigger event_dates_updated_at before update on public.event_dates for each row execute function public.set_updated_at();
drop trigger if exists promotions_updated_at on public.promotions; create trigger promotions_updated_at before update on public.promotions for each row execute function public.set_updated_at();
alter table public.events enable row level security; alter table public.event_dates enable row level security; alter table public.promotions enable row level security;
grant select on public.events,public.event_dates,public.promotions to anon; grant select,insert,update,delete on public.events,public.event_dates,public.promotions to authenticated;
drop policy if exists "public can read active events" on public.events; create policy "public can read active events" on public.events for select to anon,authenticated using (is_active = true or (select auth.uid()) is not null);
drop policy if exists "public can read dates for active events" on public.event_dates; create policy "public can read dates for active events" on public.event_dates for select to anon using (exists (select 1 from public.events e where e.id = event_id and e.is_active));
drop policy if exists "public can read promotions for active events" on public.promotions; create policy "public can read promotions for active events" on public.promotions for select to anon using (exists (select 1 from public.events e where e.id = event_id and e.is_active));
drop policy if exists "authenticated admins manage events" on public.events; create policy "authenticated admins manage events" on public.events for all to authenticated using (true) with check (true);
drop policy if exists "authenticated admins manage dates" on public.event_dates; create policy "authenticated admins manage dates" on public.event_dates for all to authenticated using (true) with check (true);
drop policy if exists "authenticated admins manage promotions" on public.promotions; create policy "authenticated admins manage promotions" on public.promotions for all to authenticated using (true) with check (true);
insert into public.events (name,category,tag,venue,pickup,base_price) values ('PERSES “UNCENSORED”','tpop','T-POP','BITEC LIVE','รับ–คืนหน้า BITEC',890),('OH MY FOURTH CONCERT','tpop','T-POP','BITEC LIVE','รับ–คืนหน้า BITEC',890),('NCT 127 THE REDLINE','kpop','K-POP','Bangkok','รับ–คืน BTS Siam / Mo Chit',1290),('BTS WORLD TOUR ARIRANG','kpop','K-POP','Rajamangala National Stadium','รับ–คืน BTS Siam / Mo Chit',1290) on conflict do nothing;
insert into public.event_dates (event_id,event_date,status) select e.id,x.event_date::date,x.status from (values ('PERSES “UNCENSORED”','2026-10-03','available'),('OH MY FOURTH CONCERT','2026-10-16','booked'),('OH MY FOURTH CONCERT','2026-10-17','available'),('OH MY FOURTH CONCERT','2026-10-18','available'),('NCT 127 THE REDLINE','2026-10-31','available'),('NCT 127 THE REDLINE','2026-11-01','available'),('BTS WORLD TOUR ARIRANG','2026-12-03','available'),('BTS WORLD TOUR ARIRANG','2026-12-05','pending'),('BTS WORLD TOUR ARIRANG','2026-12-06','available')) x(name,event_date,status) join public.events e on e.name=x.name on conflict (event_id,event_date) do nothing;
insert into public.promotions (event_id,days,discount_amount) select e.id,x.days,x.discount_amount from (values ('OH MY FOURTH CONCERT',2,80),('OH MY FOURTH CONCERT',3,270),('NCT 127 THE REDLINE',2,180)) x(name,days,discount_amount) join public.events e on e.name=x.name on conflict (event_id,days) do nothing;
do $$ begin alter publication supabase_realtime add table public.events; exception when duplicate_object then null; end $$;
do $$ begin alter publication supabase_realtime add table public.event_dates; exception when duplicate_object then null; end $$;
do $$ begin alter publication supabase_realtime add table public.promotions; exception when duplicate_object then null; end $$;
